import random
class Node:
    __slots__ = ('l', 'r', 'v', 'x', 'sz', 'pr', 'rev')
    def __init__(self, v):
        self.l = self.r = None
        self.v = v; self.x = v; self.sz = 1
        self.pr = random.random(); self.rev = False
def SZ(t): return t.sz if t else 0
def pull(t):
    t.sz = 1 + SZ(t.l) + SZ(t.r)
    t.x = t.v ^ (t.l.x if t.l else 0) ^ (t.r.x if t.r else 0)
def push(t):
    if t.rev:
        t.l, t.r = t.r, t.l
        if t.l: t.l.rev ^= True
        if t.r: t.r.rev ^= True
        t.rev = False
def split(t, k):
    if not t: return None, None
    push(t)
    if SZ(t.l) >= k:
        a, b = split(t.l, k); t.l = b; pull(t); return a, t
    a, b = split(t.r, k - SZ(t.l) - 1); t.r = a; pull(t); return t, b
def merge(a, b):
    if not a or not b: return a or b
    if a.pr > b.pr:
        push(a); a.r = merge(a.r, b); pull(a); return a
    push(b); b.l = merge(a, b.l); pull(b); return b
class Solution:
    def handleQueries(self, nums: List[int], queries: List[List[int]]) -> List[int]:
        root = None
        for v in nums:
            root = merge(root, Node(v))
        res = []
        for tp, a, b in queries:
            if tp == 2:
                l, r = a, b
                t1, rest = split(root, l)
                mid, t3 = split(rest, r - l + 1)
                res.append(mid.x if mid else 0)
                root = merge(merge(t1, mid), t3)
            elif tp == 3:
                t1, rest = split(root, a)
                mid, t3 = split(rest, b - a + 1)
                if mid: mid.rev ^= True
                root = merge(merge(t1, mid), t3)
            else:
                t1, rest = split(root, a)
                node, t3 = split(rest, 1)
                if node:
                    node.v = node.x = b
                root = merge(merge(t1, node), t3)
        return res

