struct Node {
    Node *l = nullptr, *r = nullptr;
    unsigned int pr; int v, x, sz; bool rev;
    Node(int vv) : pr(rng()), v(vv), x(vv), sz(1), rev(false) {}
    static mt19937 rng;
};
mt19937 Node::rng(chrono::steady_clock::now().time_since_epoch().count());
int sz(Node* t) { return t ? t->sz : 0; }
void pull(Node* t) { t->sz = 1 + sz(t->l) + sz(t->r); t->x = t->v ^ (t->l ? t->l->x : 0) ^ (t->r ? t->r->x : 0); }
void push(Node* t) { if (t->rev) { swap(t->l, t->r); if (t->l) t->l->rev ^= true; if (t->r) t->r->rev ^= true; t->rev = false; } }
void split(Node* t, int k, Node*& a, Node*& b) {
    if (!t) { a = b = nullptr; return; }
    push(t);
    if (sz(t->l) >= k) { split(t->l, k, a, t->l); b = t; pull(b); }
    else { split(t->r, k - sz(t->l) - 1, t->r, b); a = t; pull(a); }
}
Node* merge(Node* a, Node* b) {
    if (!a || !b) return a ? a : b;
    if (a->pr > b->pr) { push(a); a->r = merge(a->r, b); pull(a); return a; }
    push(b); b->l = merge(a, b->l); pull(b); return b;
}
class Solution {
public:
    vector<int> handleQueries(vector<int>& nums, vector<vector<int>>& queries) {
        Node* root = nullptr;
        for (int v : nums) root = merge(root, new Node(v));
        vector<int> res;
        for (auto& q : queries) {
            int tp = q[0], a = q[1], b = q[2];
            Node *t1, *mid, *t3;
            if (tp == 2) {
                split(root, a, t1, mid); split(mid, b - a + 1, mid, t3);
                res.push_back(mid ? mid->x : 0);
            } else if (tp == 3) {
                split(root, a, t1, mid); split(mid, b - a + 1, mid, t3);
                if (mid) mid->rev ^= true;
            } else {
                split(root, a, t1, mid); split(mid, 1, mid, t3);
                if (mid) { mid->v = mid->x = b; }
            }
            root = merge(merge(t1, mid), t3);
        }
        return res;
    }
};

