class Solution {
    static class Node {
        Node l, r; long pr; int v, x, sz; boolean rev;
        Node(int v) { this.v = v; this.x = v; this.sz = 1; this.pr = ThreadLocalRandom.current().nextLong(); }
    }
    static int sz(Node t) { return t == null ? 0 : t.sz; }
    static void pull(Node t) { t.sz = 1 + sz(t.l) + sz(t.r); t.x = t.v ^ (t.l == null ? 0 : t.l.x) ^ (t.r == null ? 0 : t.r.x); }
    static void push(Node t) { if (t.rev) { Node tmp = t.l; t.l = t.r; t.r = tmp; if (t.l != null) t.l.rev ^= true; if (t.r != null) t.r.rev ^= true; t.rev = false; } }
    static Node[] split(Node t, int k) {
        if (t == null) return new Node[]{null, null};
        push(t);
        Node[] res;
        if (sz(t.l) >= k) { res = split(t.l, k); t.l = res[1]; pull(t); res[1] = t; }
        else { res = split(t.r, k - sz(t.l) - 1); t.r = res[0]; pull(t); res[0] = t; }
        return res;
    }
    static Node merge(Node a, Node b) {
        if (a == null) return b;
        if (b == null) return a;
        if (a.pr > b.pr) { push(a); a.r = merge(a.r, b); pull(a); return a; }
        push(b); b.l = merge(a, b.l); pull(b); return b;
    }
    public int[] handleQueries(int[] nums, int[][] queries) {
        Node root = null;
        for (int v : nums) root = merge(root, new Node(v));
        int[] res = new int[(int) java.util.Arrays.stream(queries).filter(q -> q[0] == 2).count()];
        int ri = 0;
        for (int[] q : queries) {
            Node[] p1 = split(root, q[1]);
            Node[] p2 = split(p1[1], q[2] - q[1] + 1);
            Node mid = p2[0];
            if (q[0] == 2) res[ri++] = mid == null ? 0 : mid.x;
            else if (q[0] == 3) { if (mid != null) mid.rev ^= true; }
            else if (mid != null) { mid.v = mid.x = q[2]; }
            root = merge(merge(p1[0], mid), p2[1]);
        }
        return res;
    }
}

