var handleQueries = function(nums, queries) {
    let seed = 123456789;
    const rnd = () => (seed = (seed * 1103515245 + 12345) & 0x7fffffff) / 0x80000000;
    const mk = v => ({ l: null, r: null, v, x: v, sz: 1, pr: rnd(), rev: false });
    const sz = t => t ? t.sz : 0;
    const pull = t => { t.sz = 1 + sz(t.l) + sz(t.r); t.x = t.v ^ (t.l ? t.l.x : 0) ^ (t.r ? t.r.x : 0); };
    const push = t => { if (t.rev) { const tmp = t.l; t.l = t.r; t.r = tmp; if (t.l) t.l.rev ^= true; if (t.r) t.r.rev ^= true; t.rev = false; } };
    const split = (t, k) => {
        if (!t) return [null, null];
        push(t);
        if (sz(t.l) >= k) { const [a, b] = split(t.l, k); t.l = b; pull(t); return [a, t]; }
        const [a, b] = split(t.r, k - sz(t.l) - 1); t.r = a; pull(t); return [t, b];
    };
    const merge = (a, b) => {
        if (!a) return b; if (!b) return a;
        if (a.pr > b.pr) { push(a); a.r = merge(a.r, b); pull(a); return a; }
        push(b); b.l = merge(a, b.l); pull(b); return b;
    };
    let root = null;
    for (const v of nums) root = merge(root, mk(v));
    const res = [];
    for (const [tp, a, b] of queries) {
        const [t1, rest] = split(root, a);
        const [mid, t3] = split(rest, b - a + 1);
        if (tp === 2) res.push(mid ? mid.x : 0);
        else if (tp === 3) { if (mid) mid.rev ^= true; }
        else if (mid) { mid.v = mid.x = b; }
        root = merge(merge(t1, mid), t3);
    }
    return res;
};
